# Combination products: (id, display, names (lowercase), ingredientIds, otc)
# Ingredient lists checked against RxNorm brand -> ingredient concepts / DailyMed SPL titles (see build.py verify step).
def N(*names):
    """Names as typed. "&" and "and" need no variants (the matcher reads both as "+"); a name printed with "+"
    ("Tylenol Cold + Flu") is also typed with "plus"."""
    out = []
    for n in names:
        for f in ([n, n.replace(" + ", " plus ")] if " + " in n else [n]):
            if f not in out:
                out.append(f)
    return out


